/**
 * Jinx Poppy Grower + Summoner: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Poppy_Grower
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L118). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { ownJinxRules, storytellerPicksNow } from '#lib/core/rules/jinxes/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Poppy Grower + Summoner jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'poppygrower', 'summoner');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('poppygrower')?.name).toBe('Poppy Grower');
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['poppygrower', 'summoner'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['poppygrower'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
	});

	const ids = ['summoner', 'poppygrower', 'chef', 'empath', 'monk', 'imp'];
	const base = scenario(['summoner', 'poppygrower', 'chef', 'empath', 'monk'], {
		script: scriptOf(ids)
	});

	describe('with the Poppy Grower alive, the Storyteller chooses the summoned player', () => {
		it("is data in the Summoner's rules", () => {
			// Wiki: "If the Poppy Grower is alive on the 3rd night, the Summoner chooses which Demon but not which player."
			expect(ownJinxRules(base.game, 'summoner', 'poppygrower', base.characters)).toEqual({
				storytellerChooses: { what: 'player', when: ['partner-alive'] }
			});
		});

		it('leaves the player to the Storyteller while the Poppy Grower lives', () => {
			// Wiki: "the Summoner chooses which Demon but not which player."
			expect(storytellerPicksNow(base.game, 'summoner', base.characters)).toEqual(['poppygrower']);
		});

		it('gives the Summoner the usual choice once the Poppy Grower is dead', () => {
			// Wiki: "If the Poppy Grower is alive on the 3rd night"
			const s = base.dies('poppygrower');
			expect(storytellerPicksNow(s.game, 'summoner', s.characters)).toEqual([]);
		});
	});
});
